function maxSumOfK(nums, k) {
  if (k < 1 || k > nums.length) return null;
  let windowSum = 0;
  for (let i = 0; i < k; i++) {
    windowSum += nums[i];
  }
  let best = windowSum;
  for (let right = k; right < nums.length; right++) {
    windowSum += nums[right];      // entering
    windowSum -= nums[right - k];  // leaving
    best = Math.max(best, windowSum);
  }
  return best;
}

tests.code:
assertEqual(maxSumOfK([4, 2], 3), null);
assertEqual(maxSumOfK([], 1), null);
assertEqual(maxSumOfK([4, 2], 0), null);

let seed = 11;
const rand = (m) => { seed = (seed * 48271) % 2147483647; return seed % m; };
function brute(nums, k) {
  let best = -Infinity;
  for (let s = 0; s + k <= nums.length; s++) { let t = 0; for (let i = s; i < s + k; i++) t += nums[i]; best = Math.max(best, t); }
  return best;
}
for (let t = 0; t < 40; t++) {
  const nums = Array.from({ length: 1 + rand(12) }, () => rand(41) - 20);
  const k = 1 + rand(nums.length);
  assertEqual(maxSumOfK(nums, k), brute(nums, k), JSON.stringify(nums) + ' k=' + k);
}
